using System.Globalization;
using System.Net.Http.Headers;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using System.Text.Json.Nodes;
using EduSphere.Domain.Entities;
using EduSphere.Domain.Enums;
using EduSphere.Infrastructure;
using Microsoft.AspNetCore.DataProtection;
using Microsoft.EntityFrameworkCore;

namespace EduSphere.Web.Services;

public sealed record FinanceCheckoutResult(bool Succeeded,string? RedirectUrl,Guid? TransactionId,string? Error);
public interface IFinanceAccountingService
{
    Task<FinanceCheckoutResult> CreateCheckoutAsync(Guid invoiceId,string provider,decimal amount,string currency,string returnUrl,CancellationToken token=default);
    Task<bool> ProcessWebhookAsync(Guid tenantId,string provider,string signature,string payload,CancellationToken token=default);
    Task<(bool Succeeded,string? RefundId,string? Error)> ExecuteRefundAsync(Guid refundId,CancellationToken token=default);
    Task<JournalEntry> PostJournalAsync(JournalEntry entry,CancellationToken token=default);
    Task PostInvoiceAsync(Guid invoiceId,CancellationToken token=default);
    Task FinalizePaymentAsync(Guid paymentId,CancellationToken token=default);
    Task<int> ApplyLateFeesAsync(DateOnly asOf,CancellationToken token=default);
    Task<byte[]> BuildReceiptPdfAsync(Guid receiptId,CancellationToken token=default);
}

public sealed class FinanceAccountingService(TenantDbContext db,IHttpClientFactory clients,IDataProtectionProvider protection):IFinanceAccountingService
{
    private readonly IDataProtector protector=protection.CreateProtector("EduSphere.Administration.IntegrationSecrets.v1");
    public async Task<FinanceCheckoutResult> CreateCheckoutAsync(Guid invoiceId,string provider,decimal amount,string currency,string returnUrl,CancellationToken token=default)
    {
        provider=provider.Trim().ToLowerInvariant(); var invoice=await db.FeeInvoices.AsNoTracking().SingleAsync(x=>x.Id==invoiceId,token); if(amount<=0||amount>invoice.TotalAmount-invoice.PaidAmount)return new(false,null,null,"Amount exceeds the invoice balance.");
        var setting=await Setting(invoice.TenantId,provider,token);if(setting?.ProtectedSecret is null)return new(false,null,null,$"{provider} is not configured in tenant integrations.");
        string secret;try{secret=protector.Unprotect(setting.ProtectedSecret);}catch{return new(false,null,null,"Provider credentials could not be decrypted.");}
        string orderId;string? redirect;
        if(provider=="stripe")
        {
            using var req=new HttpRequestMessage(HttpMethod.Post,"https://api.stripe.com/v1/checkout/sessions");req.Headers.Authorization=new AuthenticationHeaderValue("Bearer",secret);req.Content=new FormUrlEncodedContent(new Dictionary<string,string>{{"mode","payment"},{"success_url",returnUrl},{"cancel_url",returnUrl},{"client_reference_id",invoice.Id.ToString()},{"line_items[0][price_data][currency]",currency.ToLowerInvariant()},{"line_items[0][price_data][unit_amount]",((long)Math.Round(amount*100)).ToString(CultureInfo.InvariantCulture)},{"line_items[0][price_data][product_data][name]",$"Fee invoice {invoice.InvoiceNumber}"},{"line_items[0][quantity]","1"},{"metadata[invoice_id]",invoice.Id.ToString()}});using var res=await clients.CreateClient().SendAsync(req,token);var body=await res.Content.ReadAsStringAsync(token);if(!res.IsSuccessStatusCode)return new(false,null,null,"Stripe rejected the checkout request.");using var json=JsonDocument.Parse(body);orderId=json.RootElement.GetProperty("id").GetString()!;redirect=json.RootElement.GetProperty("url").GetString();
        }
        else if(provider is "razorpay" or "upi")
        {
            using var config=JsonDocument.Parse(setting.ConfigurationJson);var key=config.RootElement.TryGetProperty("keyId",out var k)?k.GetString():null;if(string.IsNullOrWhiteSpace(key))return new(false,null,null,"Razorpay keyId is missing from integration configuration.");using var req=new HttpRequestMessage(HttpMethod.Post,"https://api.razorpay.com/v1/orders");req.Headers.Authorization=new AuthenticationHeaderValue("Basic",Convert.ToBase64String(Encoding.UTF8.GetBytes($"{key}:{secret}")));req.Content=JsonContent.Create(new{amount=(long)Math.Round(amount*100),currency=currency.ToUpperInvariant(),receipt=invoice.InvoiceNumber,notes=new{invoice_id=invoice.Id.ToString()}});using var res=await clients.CreateClient().SendAsync(req,token);var body=await res.Content.ReadAsStringAsync(token);if(!res.IsSuccessStatusCode)return new(false,null,null,"Razorpay rejected the order request.");using var json=JsonDocument.Parse(body);orderId=json.RootElement.GetProperty("id").GetString()!;redirect=$"/Enterprise/PaymentCheckout?order={Uri.EscapeDataString(orderId)}";
        }
        else return new(false,null,null,"Supported providers are Stripe, Razorpay and UPI through Razorpay.");
        var transaction=new OnlinePaymentTransaction{TenantId=invoice.TenantId,BranchId=invoice.BranchId,FeeInvoiceId=invoice.Id,GatewayProviderKey=provider,GatewayOrderId=orderId,Amount=amount,Currency=currency.ToUpperInvariant(),Status=PaymentGatewayStatus.Pending};db.OnlinePaymentTransactions.Add(transaction);await db.SaveChangesAsync(token);return new(true,redirect,transaction.Id,null);
    }
    public async Task<bool> ProcessWebhookAsync(Guid tenantId,string provider,string signature,string payload,CancellationToken token=default)
    {
        provider=provider.ToLowerInvariant();var webhook=await Setting(tenantId,$"{provider}-webhook",token);if(webhook?.ProtectedSecret is null)return false;string secret;try{secret=protector.Unprotect(webhook.ProtectedSecret);}catch{return false;}var valid=provider=="stripe"?VerifyStripe(signature,payload,secret):FixedEquals(signature,Hmac(payload,secret));using var doc=JsonDocument.Parse(payload);var eventId=doc.RootElement.TryGetProperty("id",out var eid)?eid.GetString()??Hash(payload):Hash(payload);if(await db.PaymentGatewayWebhookEvents.IgnoreQueryFilters().AnyAsync(x=>x.TenantId==tenantId&&x.Provider==provider&&x.EventId==eventId,token))return true;var evt=new PaymentGatewayWebhookEvent{TenantId=tenantId,Provider=provider,EventId=eventId,EventType=doc.RootElement.TryGetProperty("type",out var typ)?typ.GetString()??"unknown":"unknown",Status=valid?GatewayWebhookStatus.Verified:GatewayWebhookStatus.Rejected,PayloadHash=Hash(payload)};db.PaymentGatewayWebhookEvents.Add(evt);if(!valid){await db.SaveChangesAsync(token);return false;}
        try{var (orderId,paymentId,paid)=Extract(provider,doc.RootElement);if(paid&&!string.IsNullOrWhiteSpace(orderId)){var tx=await db.OnlinePaymentTransactions.IgnoreQueryFilters().SingleOrDefaultAsync(x=>x.TenantId==tenantId&&x.GatewayOrderId==orderId,token);if(tx is not null&&tx.Status!=PaymentGatewayStatus.Completed)await ReconcileAsync(tx,paymentId??orderId,token);}evt.Status=GatewayWebhookStatus.Processed;evt.ProcessedOn=DateTime.UtcNow;}catch(Exception ex){evt.Status=GatewayWebhookStatus.Failed;evt.Error=ex.Message[..Math.Min(1000,ex.Message.Length)];}await db.SaveChangesAsync(token);return evt.Status==GatewayWebhookStatus.Processed;
    }
    public async Task<(bool Succeeded,string? RefundId,string? Error)> ExecuteRefundAsync(Guid refundId,CancellationToken token=default)
    {
        var refund=await db.FeeRefunds.Include(x=>x.FeePayment).SingleAsync(x=>x.Id==refundId,token);if(refund.Status!=FinanceApprovalStatus.Approved)return(false,null,"Refund must be approved first.");var tx=await db.OnlinePaymentTransactions.FirstOrDefaultAsync(x=>x.FeeInvoiceId==refund.FeeInvoiceId&&x.Status==PaymentGatewayStatus.Completed,token);if(tx is null)return(false,null,"No reconciled gateway transaction was found.");var setting=await Setting(refund.TenantId,tx.GatewayProviderKey,token);if(setting?.ProtectedSecret is null)return(false,null,"Provider is not configured.");var secret=protector.Unprotect(setting.ProtectedSecret);HttpRequestMessage req;if(tx.GatewayProviderKey=="stripe"){req=new(HttpMethod.Post,"https://api.stripe.com/v1/refunds");req.Headers.Authorization=new("Bearer",secret);req.Content=new FormUrlEncodedContent(new Dictionary<string,string>{{"payment_intent",tx.GatewayPaymentId!},{"amount",((long)Math.Round(refund.Amount*100)).ToString()}});}else{using var cfg=JsonDocument.Parse(setting.ConfigurationJson);var key=cfg.RootElement.GetProperty("keyId").GetString();req=new(HttpMethod.Post,$"https://api.razorpay.com/v1/payments/{Uri.EscapeDataString(tx.GatewayPaymentId!)}/refund");req.Headers.Authorization=new("Basic",Convert.ToBase64String(Encoding.UTF8.GetBytes($"{key}:{secret}")));req.Content=JsonContent.Create(new{amount=(long)Math.Round(refund.Amount*100)});}using var res=await clients.CreateClient().SendAsync(req,token);var body=await res.Content.ReadAsStringAsync(token);if(!res.IsSuccessStatusCode)return(false,null,"Provider rejected the refund.");using var json=JsonDocument.Parse(body);var id=json.RootElement.GetProperty("id").GetString();refund.GatewayRefundId=id;refund.Status=FinanceApprovalStatus.Processed;refund.ProcessedOn=DateTime.UtcNow;refund.FeePayment!.Status=PaymentStatus.Refunded;var invoice=await db.FeeInvoices.SingleAsync(x=>x.Id==refund.FeeInvoiceId,token);invoice.PaidAmount=Math.Max(0,invoice.PaidAmount-refund.Amount);invoice.Status=invoice.PaidAmount==0?InvoiceStatus.Issued:InvoiceStatus.PartiallyPaid;await PostSystemJournal(refund.TenantId,refund.BranchId,VoucherType.Payment,$"Refund {id}",refund.Id,"FeeRefund","4100","1100",refund.Amount,token);await db.SaveChangesAsync(token);return(true,id,null);
    }
    public async Task<JournalEntry> PostJournalAsync(JournalEntry entry,CancellationToken token=default)
    {
        if(entry.Lines.Count<2||entry.Lines.Sum(x=>x.Debit)!=entry.Lines.Sum(x=>x.Credit)||entry.Lines.Sum(x=>x.Debit)<=0)throw new InvalidOperationException("A journal must contain balanced debit and credit lines.");
        if(entry.TenantId==Guid.Empty){var account=await db.ChartOfAccounts.IgnoreQueryFilters().AsNoTracking().SingleAsync(x=>x.Id==entry.Lines.First().ChartOfAccountId,token);entry.TenantId=account.TenantId;entry.BranchId??=account.BranchId;foreach(var line in entry.Lines)line.TenantId=account.TenantId;}
        if(await db.AccountingPeriods.IgnoreQueryFilters().AnyAsync(x=>x.TenantId==entry.TenantId&&(x.BranchId==null||x.BranchId==entry.BranchId)&&x.Status==AccountingPeriodStatus.Closed&&entry.PostingDate>=x.StartsOn&&entry.PostingDate<=x.EndsOn,token))throw new InvalidOperationException("The accounting period is closed.");entry.Status=JournalStatus.Posted;entry.PostedOn=DateTime.UtcNow;db.JournalEntries.Add(entry);await db.SaveChangesAsync(token);return entry;
    }
    public async Task PostInvoiceAsync(Guid invoiceId,CancellationToken token=default){if(await db.JournalEntries.AnyAsync(x=>x.SourceType=="FeeInvoice"&&x.SourceEntityId==invoiceId,token))return;var invoice=await db.FeeInvoices.SingleAsync(x=>x.Id==invoiceId,token);await PostSystemJournal(invoice.TenantId,invoice.BranchId,VoucherType.DebitNote,$"Fee invoice {invoice.InvoiceNumber}",invoice.Id,"FeeInvoice","1200","4100",invoice.TotalAmount,token);}
    public async Task FinalizePaymentAsync(Guid paymentId,CancellationToken token=default){if(await db.JournalEntries.AnyAsync(x=>x.SourceType=="FeePayment"&&x.SourceEntityId==paymentId,token))return;var payment=await db.FeePayments.Include(x=>x.FeeInvoice).SingleAsync(x=>x.Id==paymentId,token);if(payment.Status!=PaymentStatus.Completed)return;var invoice=payment.FeeInvoice!;invoice.PaidAmount=Math.Min(invoice.TotalAmount,invoice.PaidAmount+payment.Amount);invoice.Status=invoice.PaidAmount>=invoice.TotalAmount?InvoiceStatus.Paid:InvoiceStatus.PartiallyPaid;if(!await db.FeeReceipts.AnyAsync(x=>x.FeePaymentId==payment.Id,token)){var number=await NextNumber(payment.TenantId,payment.BranchId,"Receipt",token);db.FeeReceipts.Add(new(){TenantId=payment.TenantId,BranchId=payment.BranchId,FeePaymentId=payment.Id,ReceiptNumber=number});}await PostSystemJournal(payment.TenantId,payment.BranchId,VoucherType.Receipt,$"Fee receipt {payment.PaymentNumber}",payment.Id,"FeePayment","1100","1200",payment.Amount,token);await db.SaveChangesAsync(token);}
    public async Task<int> ApplyLateFeesAsync(DateOnly asOf,CancellationToken token=default){var changed=0;var invoices=await db.FeeInvoices.Where(x=>x.Status!=InvoiceStatus.Paid&&x.Status!=InvoiceStatus.Cancelled&&x.DueDate<asOf).ToListAsync(token);foreach(var invoice in invoices){var rule=await db.LateFeeRules.Where(x=>x.IsActive&&(x.BranchId==null||x.BranchId==invoice.BranchId)).OrderByDescending(x=>x.BranchId.HasValue).FirstOrDefaultAsync(token);if(rule is null||asOf.DayNumber-invoice.DueDate.DayNumber<=rule.GraceDays)continue;var days=asOf.DayNumber-invoice.DueDate.DayNumber-rule.GraceDays;var fee=rule.Method==LateFeeMethod.Fixed?rule.Value:rule.Method==LateFeeMethod.PerDay?rule.Value*days:(invoice.TotalAmount-invoice.PaidAmount)*rule.Value/100m;if(rule.MaximumAmount.HasValue)fee=Math.Min(fee,rule.MaximumAmount.Value);if(fee<=invoice.FineAmount)continue;invoice.TotalAmount+=fee-invoice.FineAmount;invoice.FineAmount=fee;invoice.Status=InvoiceStatus.Overdue;changed++;}await db.SaveChangesAsync(token);return changed;}
    public async Task<byte[]> BuildReceiptPdfAsync(Guid receiptId,CancellationToken token=default){var receipt=await db.FeeReceipts.Include(x=>x.FeePayment)!.ThenInclude(x=>x!.FeeInvoice).Include(x=>x.Branch).SingleAsync(x=>x.Id==receiptId,token);var p=receipt.FeePayment!;var lines=new[]{receipt.Branch?.Name??"EduSphere","OFFICIAL FEE RECEIPT",$"Receipt: {receipt.ReceiptNumber}",$"Invoice: {p.FeeInvoice?.InvoiceNumber}",$"Payment: {p.PaymentNumber}",$"Date: {receipt.IssuedOn:dd MMM yyyy}",$"Amount: {p.Amount:0.00}",$"Mode: {p.Mode}",$"Reference: {p.TransactionReference}"};return SimplePdf(lines);}
    private async Task ReconcileAsync(OnlinePaymentTransaction tx,string paymentId,CancellationToken token){tx.Status=PaymentGatewayStatus.Completed;tx.GatewayPaymentId=paymentId;tx.CompletedOn=DateTime.UtcNow;var invoice=await db.FeeInvoices.IgnoreQueryFilters().SingleAsync(x=>x.Id==tx.FeeInvoiceId,token);var payment=new FeePayment{TenantId=tx.TenantId,BranchId=tx.BranchId,FeeInvoiceId=tx.FeeInvoiceId,PaymentNumber=$"PAY-{paymentId}"[..Math.Min(60,$"PAY-{paymentId}".Length)],PaidOn=DateTime.UtcNow,Amount=tx.Amount,Mode=PaymentMode.OnlineGateway,Status=PaymentStatus.Completed,TransactionReference=paymentId};db.FeePayments.Add(payment);invoice.PaidAmount=Math.Min(invoice.TotalAmount,invoice.PaidAmount+tx.Amount);invoice.Status=invoice.PaidAmount>=invoice.TotalAmount?InvoiceStatus.Paid:InvoiceStatus.PartiallyPaid;await db.SaveChangesAsync(token);var number=await NextNumber(tx.TenantId,tx.BranchId,"Receipt",token);db.FeeReceipts.Add(new FeeReceipt{TenantId=tx.TenantId,BranchId=tx.BranchId,FeePaymentId=payment.Id,ReceiptNumber=number});await PostSystemJournal(tx.TenantId,tx.BranchId,VoucherType.Receipt,$"Gateway receipt {paymentId}",payment.Id,"FeePayment","1100","1200",tx.Amount,token);}
    private async Task PostSystemJournal(Guid tenantId,Guid branchId,VoucherType type,string narration,Guid source,string sourceType,string debitCode,string creditCode,decimal amount,CancellationToken token){var accounts=await EnsureAccounts(tenantId,branchId,token);var entry=new JournalEntry{TenantId=tenantId,BranchId=branchId,JournalNumber=$"JV-{DateTime.UtcNow:yyyyMMddHHmmssfff}",PostingDate=DateOnly.FromDateTime(DateTime.UtcNow),VoucherType=type,Narration=narration,SourceEntityId=source,SourceType=sourceType,Lines=[new(){TenantId=tenantId,ChartOfAccountId=accounts[debitCode].Id,Debit=amount},new(){TenantId=tenantId,ChartOfAccountId=accounts[creditCode].Id,Credit=amount}]};await PostJournalAsync(entry,token);}
    private async Task<Dictionary<string,ChartOfAccount>> EnsureAccounts(Guid tenantId,Guid branchId,CancellationToken token){var defs=new[]{("1100","Bank / Gateway Clearing",AccountType.Asset),("1200","Student Fee Receivable",AccountType.Asset),("4100","Fee Income",AccountType.Income)};var found=await db.ChartOfAccounts.IgnoreQueryFilters().Where(x=>x.TenantId==tenantId).ToListAsync(token);foreach(var d in defs.Where(d=>found.All(x=>x.Code!=d.Item1))){var a=new ChartOfAccount{TenantId=tenantId,BranchId=branchId,Code=d.Item1,Name=d.Item2,Type=d.Item3};db.ChartOfAccounts.Add(a);found.Add(a);}await db.SaveChangesAsync(token);return found.ToDictionary(x=>x.Code);}
    private async Task<string> NextNumber(Guid tenantId,Guid branchId,string type,CancellationToken token){var seq=await db.FinanceNumberSequences.IgnoreQueryFilters().SingleOrDefaultAsync(x=>x.TenantId==tenantId&&x.BranchId==branchId&&x.DocumentType==type,token);if(seq is null){seq=new(){TenantId=tenantId,BranchId=branchId,DocumentType=type};db.Add(seq);}var n=seq.NextNumber++;var fy=DateTime.UtcNow.Month>=seq.FinancialYearStartMonth?$"{DateTime.UtcNow:yy}-{DateTime.UtcNow.AddYears(1):yy}":$"{DateTime.UtcNow.AddYears(-1):yy}-{DateTime.UtcNow:yy}";return seq.Format.Replace("{BRANCH}",branchId.ToString("N")[..4].ToUpperInvariant()).Replace("{FY}",fy).Replace("{SEQ:000000}",n.ToString("000000"));}
    private Task<TenantIntegrationSetting?> Setting(Guid tenant,string key,CancellationToken token)=>db.TenantIntegrationSettings.IgnoreQueryFilters().AsNoTracking().FirstOrDefaultAsync(x=>x.TenantId==tenant&&x.IntegrationKey==key&&x.IsEnabled,token);
    private static (string? Order,string? Payment,bool Paid) Extract(string provider,JsonElement root){if(provider=="stripe"){var obj=root.GetProperty("data").GetProperty("object");return(obj.GetProperty("id").GetString(),obj.TryGetProperty("payment_intent",out var p)?p.GetString():null,obj.TryGetProperty("payment_status",out var s)&&s.GetString()=="paid");}var pay=root.GetProperty("payload").GetProperty("payment").GetProperty("entity");return(pay.GetProperty("order_id").GetString(),pay.GetProperty("id").GetString(),pay.GetProperty("status").GetString()=="captured");}
    private static bool VerifyStripe(string header,string body,string secret){var parts=header.Split(',').Select(x=>x.Split('=',2)).Where(x=>x.Length==2).ToDictionary(x=>x[0],x=>x[1]);return parts.TryGetValue("t",out var t)&&parts.TryGetValue("v1",out var v)&&FixedEquals(v,Hmac($"{t}.{body}",secret));}
    private static string Hmac(string value,string key)=>Convert.ToHexString(HMACSHA256.HashData(Encoding.UTF8.GetBytes(key),Encoding.UTF8.GetBytes(value))).ToLowerInvariant();private static bool FixedEquals(string a,string b)=>CryptographicOperations.FixedTimeEquals(Encoding.UTF8.GetBytes(a),Encoding.UTF8.GetBytes(b));private static string Hash(string s)=>Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(s)));
    private static byte[] SimplePdf(IEnumerable<string> lines){var text=string.Join("\\n",lines).Replace("(","\\(").Replace(")","\\)");var stream=$"BT /F1 12 Tf 48 790 Td 18 TL ({text.Replace("\\n",") Tj T* (")}) Tj ET";var objs=new[]{"<< /Type /Catalog /Pages 2 0 R >>","<< /Type /Pages /Kids [3 0 R] /Count 1 >>","<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 842] /Resources << /Font << /F1 5 0 R >> >> /Contents 4 0 R >>",$"<< /Length {Encoding.ASCII.GetByteCount(stream)} >>\nstream\n{stream}\nendstream","<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold >>"};var sb=new StringBuilder("%PDF-1.4\n");var offsets=new List<int>{0};for(var i=0;i<objs.Length;i++){offsets.Add(Encoding.ASCII.GetByteCount(sb.ToString()));sb.Append($"{i+1} 0 obj\n{objs[i]}\nendobj\n");}var xref=Encoding.ASCII.GetByteCount(sb.ToString());sb.Append($"xref\n0 {objs.Length+1}\n0000000000 65535 f \n");foreach(var o in offsets.Skip(1))sb.Append($"{o:0000000000} 00000 n \n");sb.Append($"trailer << /Size {objs.Length+1} /Root 1 0 R >>\nstartxref\n{xref}\n%%EOF");return Encoding.ASCII.GetBytes(sb.ToString());}
}
